    source_name, source_url, processing_weeks_min, processing_weeks_max,
    government_fee_minor, government_fee_currency,
    is_live, last_verified_at, review_state, approved_by, approved_at,
    reject_reason, source_hash
  )
  values ('gh', 'ae', 'tourism', 'UAE Tourist/Visit Visa', 1, date '2026-09-12', 'VFS Global, Ghana (UAE visa services)', 'https://www.vfsglobal.com/one-pager/uae/ghana/english/', 1, 1, 122500, 'GHS', false, null, 'pending', null, null, null, '362044c9b58c83363d7ca949cab60018761f5eeafcd30adbb756aa32de23b866')
