from c, (values
  ('visa_application_form', 'the visa application form received by e-mail, completed, signed and printed out', 'Submitted on the day of the appointment.', 'application_form', true, 1, 'https://dofi.ibz.be/en/themes/ressortissants-dun-pays-tiers/regroupement-familial/visa-d-application-family-reunification'),
  ('appointment_confirmation', 'the appointment confirmation', 'Submitted on the day of the appointment.', 'appointment', true, 2, 'https://dofi.ibz.be/en/themes/ressortissants-dun-pays-tiers/regroupement-familial/visa-d-application-family-reunification'),
  ('travel_document', 'a personal travel document in which a visa can be affixed', 'If the applicant is unable to present this document, another proof of identity (or several other proofs of identity) to which the competent Belgian diplomatic or consular post gives weight may be presented. When the visa is issued, this document must be valid for at least 12 months.', 'identity_travel', true, 3, 'https://dofi.ibz.be/en/themes/ressortissants-dun-pays-tiers/regroupement-familial/visa-d-application-family-reunification'),
  ('alternative_proof_of_identity', 'another proof of identity (or several other proofs of identity)', 'May be presented if the applicant is unable to present a personal travel document in which a visa can be affixed. For family members of a foreign national whose refugee status has been recognised by Belgium or to whom Belgium has granted subsidiary protection, applicants who do not present a valid travel document when submitting their application must prove their full identity by other means of evidence; the competent post determines the alternative documents that can be presented in the specific local context.', 'identity_travel', false, 4, 'https://dofi.ibz.be/en/themes/ressortissants-dun-pays-tiers/regroupement-familial/visa-d-application-family-reunification'),
  ('proof_of_payment_handling_fee', 'proof of payment of the handling fee', 'Required unless exempted.', 'fee_payment', false, 5, 'https://dofi.ibz.be/en/themes/ressortissants-dun-pays-tiers/regroupement-familial/visa-d-application-family-reunification'),
  ('proof_of_payment_fee', 'proof of payment of the fee', 'Required unless exempted.', 'fee_payment', false, 6, 'https://dofi.ibz.be/en/themes/ressortissants-dun-pays-tiers/regroupement-familial/visa-d-application-family-reunification'),
