from c, (values
  ('national_visa_application_form', 'duly completed visa application form for a national visa (long stay)', 'Open the online application form Videx; fill it in fully and correctly in English or German; download the completed form as a PDF-file; print it (should be 6 pages including a barcode on the last page); date and sign it.', 'application_form', true, 1, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('passport_photo', '1 recent passport photograph according to biometric specifications', null, 'photo', true, 2, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('passport', 'Original passport (or travel document)', 'Valid for at least 3 months longer than the intended stay. It must contain at least two blank pages and must have been issued within the last 10 years.', 'passport', true, 3, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('passport_copies', 'Provide a copy of a) the passport data page, b) previous Schengen visas within last 3 years and c) valid USA/UK visas if available.', null, 'passport', true, 4, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('proof_of_legal_residence_in_namibia', 'Proof of legal residence in Namibia', 'For Non-Namibian citizens.', 'residence_status', false, 5, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('employment_contract_or_letter_of_intent', 'copy of the signed employment contract or letter of intent from the future employer in Germany', 'Including details about salary, working hours and duration of employment as well as full address of the employer.', 'employment', true, 6, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('self_employment_company_and_financing_informatio', 'for self-employment: copy of all information regarding the company and financing', 'E.g. location offer, business plan, credit and financial information, business contracts in Germany.', 'employment', false, 7, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('job_description', 'detailed job description from the future employer', null, 'employment', true, 8, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('proof_of_qualifications', 'Proof of qualifications entitling the applicant to the aspired occupation in Germany', 'E. g. university degree etc., please check with the recognized information platform ANABIN.', 'qualification', true, 9, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('declaration_of_employment', 'Declaration of employment by the future employer (Erklärung zum Beschäftigungsverhältnis)', null, 'employment', true, 10, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('pre_approval_local_work_agency', 'Pre-approval from the local work agency (Bundesagentur für Arbeit)', 'If applicable.', 'employment_authorization', false, 11, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('proof_of_accommodation', 'Proof of accommodation in Germany with full address', 'E. g. renting contract, hotel reservation or invitation letter in case of private accommodation with name, full address and passport copy of inviting person.', 'accommodation', true, 12, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('flight_reservation_itinerary', 'Flight reservation / itinerary with the applicant’s name', 'Only to be provided after the approval of the visa. No final booking needed.', 'travel', true, 13, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf'),
  ('travel_medical_insurance', 'Travel/medical insurance with policy wording', 'Only to be provided after the approval of the visa. Coverage for medical expenses/repatriation/pre-existing: EUR 30,000, valid for the entire Schengen area for the duration of the applicant''s planned stay. It is a requirement that claims against the insurance company must be recoverable in a Member State. The insured party, policy validity period, geographical coverage and schedule of benefits must be mentioned in the policy schedule/certificate.', 'insurance', true, 14, 'https://windhuk.diplo.de/resource/blob/2123336/f75aae6dce9fcc3456869c237d35c8e8/merkblatt-national-work-visa-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

