from c, (values
  ('application_form', 'One (1) fully completed and signed application including declaration pursuant to Section 54 Residence Act', null, 'application', true, 1, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('passport_photo', 'One (1) recent biometric passport photo', 'see specimen photos', 'photo', true, 2, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('passport', 'Valid and personally signed passport with at least two (2) completely empty pages', null, 'passport', true, 3, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('passport_data_page_copy', 'One (1) uncertified copy of the data page of your valid passport', null, 'passport', true, 4, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('declaration_of_employment', 'Completed form signed by your employer: Declaration of employment', 'original with one (1) copy', 'employment', true, 5, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('old_age_provision', 'Proof of adequate provision for old age', 'original and one (1) copy; only if salary does not amount to at least 55% of the annual contribution assessment ceiling for the general pension insurance scheme – 2026: € 55 770 gross per annum; from the age of 45', 'financial', false, 6, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('university_qualification', 'Proof of qualification: University qualification', 'all pages, original and one (1) copy', 'education', true, 7, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('anabin_printout', 'One (1) printout from the anabin database on the qualification and on the institution', 'under proof of recognition of the qualification', 'education', false, 8, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('statement_of_comparability', 'Statement of Comparability by the Central Office for Foreign Education (ZAB)', 'original with one (1) copy; if the qualification is not assessed as “entspricht” (comparable) or “gleichwertig” (equivalent) and/or the institution is not classified as “H+”', 'education', false, 9, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('permission_to_exercise_profession', 'Permission to exercise a profession issued by the authority responsible for recognising qualifications or assurance of permission to exercise a profession', 'original and one (1) copy; in the case of regulated professions in which permission is required to exercise the profession, for example, doctors, engineers; for medical professions: decision of the licensing authority in the federal territory, i.e. assurance of permission to exercise a profession and/or issuing of medical licence', 'professional_authorisation', false, 10, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf'),
  ('health_insurance', 'Proof of adequate health insurance cover', 'If as an employee you are subject to mandatory statutory health insurance, this insurance can only begin when you take up residence in Germany and enter into employment. If you enter Germany beforehand, private health insurance must be taken out for the period prior to employment beginning and prior to being eligible for statutory health insurance. Travel health insurance and so-called incoming travel insurance can contain exclusions if a long-term or permanent stay is planned.', 'insurance', true, 11, 'https://southafrica.diplo.de/resource/blob/2295092/a70e886361b7bfe1cc1f73f2b9f57b36/visad-mb-w-skilled-workers-uni-degree-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

