select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'Passport', 'Original passport + copy of data page; valid for at least 6 more months and at least two free pages.', 'identity', true, 1, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('birth_certificate', 'Birth certificate', 'Based on first registration.', 'civil_status', true, 2, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('school_leaving_certificates', 'School leaving certificates', 'WAEC-certificates: BECE and WASSCE.', 'education', true, 3, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('curriculum_vitae', 'Curriculum vitae (CV)', 'Including the following points: specification of the certificates, diplomas and qualifications obtained; professional training; work experience.', 'employment', true, 4, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('proof_of_employment_in_germany', 'Proof of Employment in Germany', 'Employment contract or binding job offer for a qualified occupation, containing: the time frame of the contract; a detailed job description; the gross annual salary; working hours; annual holidays; place of work.', 'employment', true, 5, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('proof_of_qualifications', 'Proof of Qualifications', 'For workers with University degree: a German university degree or a recognized foreign university degree; whether the degree is recognized has to be checked at ANABIN database, and a printout confirming the recognition needs to be handed in. If the qualification is not assessed as “entspricht” (comparable) or “gleichwertig” (equivalent) and/or the institution is not classified as “H+”, you will first have to apply for a Statement of Comparability with the Central Office for Foreign Education before applying for a visa. For workers with vocational training: German vocational qualification or proof of possession of a foreign professional qualification that is recognized by the competent German authority as equivalent to a German qualification.', 'education', true, 6, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('health_insurance', 'Health insurance', 'Incoming-health insurance valid from the day of entering Germany until the work contract starts. A travel health insurance is not sufficient.', 'insurance', true, 7, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('residence_permit_for_ghana', 'Residence permit for Ghana, if applicable', 'As proof of a legal residence status in Ghana; only for applicants with a nationality other than Ghanaian, Liberian or Sierra Leonean.', 'residency', false, 8, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('permission_to_exercise_the_profession', 'Permission to exercise the profession, if applicable', 'In the case of regulated professions, for example doctors or engineers, a permission to exercise the profession issued by the authority responsible for recognising qualifications or assurance of permission to exercise a profession.', 'professional_authorization', false, 9, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('german_language_certificate', 'German language certificate, if applicable', 'If necessary for the employment in Germany, in form of a recognized certificate, not older than one year.', 'language', false, 10, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('proof_of_adequate_provision_for_old_age', 'Proof of adequate provision for old age, if applicable', 'From the age of 45 years; only if salary does not amount to at least 55% of the annual contribution assessment ceiling for the general pension insurance scheme – 2026: 55,770 € gross/per annum.', 'financial', false, 11, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('biometric_photograph', '1 biometric photograph', 'Not older than 6 months; uniform white background; size: 3.5x4,5 cm; not glued or stapled to the application form.', 'photo', true, 12, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322'),
  ('original_documents', 'Original documents', 'You will receive the information, which documents are needed in the Consular Service Portal.', 'supporting_documents', true, 13, 'https://accra.diplo.de/gh-en/service/-visainformation/2615322-2615322')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

