  )
  values ('eg', 'de', 'study', 'National Visa for Study', 1, date '2026-09-14', 'German Embassy Cairo', 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf', 4, 5, 7500, 'EUR', false, null, 'pending', null, null, null, '9fc2f6f2d331d7b6ba4bb890189c5aaedfb640de8b57433b3222c4495d9cf7db')
