insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'PASSPORT (ORIGINAL AND 2 COPIES)', 'Passport is not older than ten years, has at least two blank pages left and is not damaged. The passport is valid for three months after the returning date. The passport holder has signed the passport before submitting the application. The passport holder is clearly to be identified with the passport photo. Copies of the data page, page 3 and previous visas (Schengen Visa, USA, UK, CAN). Copies of the last existing visas in the old passports have been made.', 'identity', true, 1, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('national_visa_application_form', 'APPLICATION FORMS AND 2 INSTRUCTIONS', 'Fully completed and personally signed national visa application form (VIDEX) and the accompanying instruction.', 'application_form', true, 2, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('biometric_passport_photos', 'CURRENT BIOMETRIC PASSPORT PICTURE (3 PICTURES)', '2 pictures are glued to the 2 applications, 1 picture is used for the scan. The passport photo is not older than 6 months. The passport photo is taken with a white or light gray background. The passport photo has not been digitally modified.', 'photo', true, 3, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('health_insurance', 'PROOF OF ADEQUATE HEALTH INSURANCE COVER (2 COPIES)', 'The insurance is valid for all Schengen countries. The minimum coverage amount is €30,000 or equivalent in US-Dollar. There is no limit or exclusion of treatment (Covid19, pregnancy, age restriction etc.). If you enter Germany beforehand, private health insurance must be taken out for the period between entry into Germany and enrolment and registering for statutory health insurance.', 'insurance', true, 4, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('curriculum_vitae', 'CURRICULUM VITAE (ORIGINAL + 1 COPY)', 'Was written by yourself, is completely traceable, contains a description of your training to date, and is signed by yourself.', 'supporting_document', true, 5, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('professional_activity_supporting_documents', 'supporting documents', 'Supporting documents for information on your previous professional activities in the curriculum vitae.', 'supporting_document', false, 6, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('motivation_letter', 'MOTIVATION LETTER (ORIGINAL + 1 COPY)', 'Was written and signed by yourself. Explains your choice of study subject, motivation, expectations and reasons to enroll for a study program in Germany.', 'letter', true, 7, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('high_school_or_university_diploma', 'HIGH SCHOOL OR UNIVERSITY DIPLOMA (S) (ORIGINAL + 2 COPIES)', 'You only have to submit your last obtained high school degree or university degree with performance record. You need to translate and legalize your degree.', 'education', true, 8, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('proof_of_admittance', 'Proof of admittance to a study course at a German university or a preparatory college in Germany (“Zulassungsbescheid”)', 'Including information on the language of instruction.', 'education', true, 9, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('language_proof', 'Proof of B1 German language skills', 'If your study program is taught in English, please submit evidence of your English language level. The embassy only accepts B1 language certificates of recognized testing centres which follow the “Standards of the Association of Language Testers in Europe” (ALTE).', 'language', true, 10, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('proof_of_adequate_financial_means', 'PROOF OF ADEQUATE FINANCIAL MEANS (ORIGINAL AND 2 COPIES)', 'To stay in Germany the applicant must have at their disposal at least 934 Euro per month. Financial funds must be proven for at least one year that is at least 11.208 Euro.', 'financial', true, 11, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('blocked_bank_account', 'blocked bank account', 'Minimum 11.208 Euro per year, 934 Euro per month. When applying for a visa, only the official confirmation of the opening of the account including information on the amount paid in and the amount available per month will be accepted.', 'financial', false, 12, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('scholarship_letter', 'letter of scholarship by an official German institution or program (e.g. DAAD, Erasmus)', 'Can be used to prove that you have enough financial means.', 'financial', false, 13, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf'),
  ('formal_obligation', 'formal obligation (German: “Verpflichtungserklärung”)', 'By a person living in Germany for the duration of your studies. Can be used to prove that you have enough financial means.', 'financial', false, 14, 'https://kairo.diplo.de/resource/blob/2546508/b249cc765b49519705d54e85f137f1d8/merkblatt-eng-studium-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

