  ('passport', 'Passaporte, com cópia', 'válido pelo menos um ano a partir da chegada prevista em Alemanha', 'identity', true, 2, 'https://maputo.diplo.de/resource/blob/1050444/bc03bafb80632ee3d0c695b1bb210ed4/mb-studiumpt-data.pdf'),
  ('passport_data_page_copies', 'Duas fotocópias simples da página de dados pessoais do passaporte', null, 'identity', true, 3, 'https://maputo.diplo.de/resource/blob/1050444/bc03bafb80632ee3d0c695b1bb210ed4/mb-studiumpt-data.pdf'),
  ('biometric_photos', 'Duas fotografias biométricas tipo passaporte (35x45mm)', null, 'photo', true, 4, 'https://maputo.diplo.de/resource/blob/1050444/bc03bafb80632ee3d0c695b1bb210ed4/mb-studiumpt-data.pdf'),
