insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('cv', 'Curriculum vitae', 'Veuillez fournir un CV sous forme de tableau avec des informations précises.', 'personal_documents', true, 1, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('motivation_letter', 'Lettre de motivation', 'Dans une lettre rédigée par vous-même, expliquez pourquoi vous souhaitez vous engager, quelles sont vos attentes par rapport à des études en Allemagne et en quoi ce séjour peut vous être utile pour votre avenir. Abordez également vos perspectives professionnelles après vos études. Veuillez signer la lettre de motivation de votre propre main.', 'supporting_letter', true, 2, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('study_questionnaire', 'Questionnaire pour étudier en Allemagne', 'Veuillez remplir le questionnaire suivant et le présenter.', 'form', true, 3, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('admission_letter', 'Lettre d''admission', 'Il faut présenter une décision d''admission d''une haute école spécialisée ou d''une université allemande. Pour les participants des établissements préparatoires aux études supérieures uniquement : il faut présenter une décision d''admission correspondante.', 'education', true, 4, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('fsp_pass_certificate', 'preuve de réussite de l''examen FSP', 'À fournir si vous avez déjà passé l’examen de constatation (FSP) avec succès au Maroc.', 'education', false, 5, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('preparatory_courses_proof', 'justificatif des cours préparatoires déjà réussis au Maroc', 'À présenter si vous allez passer l''examen FSP en Allemagne.', 'education', false, 6, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('registration_fees_paid_proof', 'frais d''inscription déjà payés', 'À présenter si vous allez passer l''examen FSP en Allemagne.', 'financial', false, 7, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('university_result_certificates', 'certificats de résultats universitaires', 'Si vous disposez de certificats de réussite universitaire, veuillez les soumettre.', 'education', false, 8, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('language_certificate', 'Certificat de langue', 'Vous devez prouver que vous avez des connaissances en allemand d''au moins le niveau B1 du Cadre européen commun de référence pour les langues. Cela s''applique à la langue d''enseignement des études. Le certificat de langue présenté ne doit pas dater de plus de 12 mois au moment de la demande. Si la langue d''enseignement est l''allemand, veuillez présenter un certificat d''un prestataire d''examens reconnu. Si la langue d''enseignement est l''anglais, les connaissances linguistiques correspondantes peuvent être prouvées par des certificats IELTS ou TOEFL.', 'language', true, 9, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('health_insurance', 'Assurance maladie', 'Si l''arrivée a lieu avant l''immatriculation et l''admission dans l''assurance maladie légale, il faut souscrire une assurance maladie privée jusqu''à ce que celles-ci aient lieu.', 'insurance', true, 10, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('proof_of_financial_means', 'Preuve que vous avez suffisamment de moyens de subsistance', 'Vous avez plusieurs possibilités à cet effet : versement d''une garantie sur un compte bloqué en Allemagne à partir d''un montant de 11.904,- euros avec versement mensuel de 992,- euros. Les candidats à une inscription à l’université doivent verser une caution d’un montant minimum de 13.092 euros, avec un versement mensuel de 1.091 euros sur le compte bloqué. Déclaration de prise en charge conformément aux articles 66-68 de la loi allemande sur le séjour des étrangers par une personne vivant en Allemagne pour la durée probable des études (mais au moins pour un an), avec vérification de la solvabilité. Uniquement pour les boursiers : promesse de bourse avec mention du montant.', 'financial', true, 11, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('scholarship_promise', 'promesse de bourse avec mention du montant', 'Uniquement pour les boursiers.', 'financial', false, 12, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206'),
  ('bafoeg_notice_2024', 'Notice d''information sur l''augmentation de la loi fédérale sur les aides à la formation (BAföG) 2024', 'dûment remplie', 'form', true, 13, 'https://rabat.diplo.de/ma-fr/service/visa-einreise/2732206-2732206')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

