insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'Passeport', 'Passeport biométrique valable au moins six mois.', 'identity', true, 1, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('biometric_photo', 'Photo d’identité biométrique', 'Photos d’identité récentes respectant les critères de la biométrie.', 'photo', true, 2, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('ivory_coast_residence_proof', 'Preuve que vous résidez en Côte d’Ivoire', 'Les non-Ivoiriens doivent présenter leur permis de séjour en cours de validité pour la Côte d''Ivoire, excepté les résidents de la CEDEAO muni de la carte consulaire délivrée par l''ambassade de leur pays d''origine.', 'residency', false, 3, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('birth_certificate', 'Acte de naissance', 'Copie intégrale d''acte de naissance. Si l’acte de naissance est basé sur un jugement supplétif, il faut le présenter également.', 'civil_status', true, 4, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('university_admission', 'Admission de l’université', 'Attestation de l''université/de l''établissement d''enseignement supérieur concernant l''admission aux études/au Studienkolleg avec mention de la langue d''enseignement. Pour les cursus en anglais, les connaissances en langue anglaise requises (par ex. certificat TOEFL) doivent être présentées.', 'education', true, 5, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('language_of_instruction_proof', 'preuve des connaissances linguistiques dans la langue d''enseignement', 'Si l''université ne le confirme pas dans sa décision d''admission : preuve des connaissances linguistiques dans la langue d''enseignement est nécessaire pour les études ou les études préparatoires (sans cours de langue préparatoire aux études, en règle générale au moins B2 dans la langue d''enseignement).', 'language', false, 6, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('conditional_admission_language_course_enrolment', 'inscription au cours de langue intensif de préparation aux études', 'En cas d''admission conditionnelle : inscription au cours de langue intensif de préparation aux études correspondant à votre niveau linguistique et comprenant au moins 20 heures par semaine.', 'language', false, 7, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('proof_of_financial_means', 'Preuve de moyens financiers', 'Pour son séjour en Allemagne, le demandeur doit disposer d''au moins 992 EUR /mois (11.904 € /an). Lors du dépôt de la demande, les moyens financiers doivent être prouvés pour au moins un an, soit au moins 11.904 € (par exemple par un compte bloqué ou une déclaration formelle d''engagement (Verpflichtungserklärung)).', 'financial', true, 8, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('blocked_account_confirmation', 'confirmation d''ouverture officielle', 'En cas de financement par compte bloqué : ouvrez le compte bloqué suffisamment tôt AVANT la demande de visa. Lors de la demande de visa, seule la confirmation d''ouverture officielle mentionnant le montant total versé et le montant mensuel disponible sera acceptée. Une confirmation sans mention de ces montants n''est pas suffisante.', 'financial', false, 9, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('declaration_of_commitment', 'déclaration de prise en charge', 'En cas de financement par une déclaration de prise en charge, la déclaration doit porter la mention "justifiée" (nachgewiesen) par le service des étrangers. Les déclarations de prise en charge qui portent la mention "crédible" (glaubhaft gemacht) comme preuve de financement des études ne peuvent pas être acceptées pour la demande. L’original de la déclaration doit être présentée lors de la demande de visa.', 'financial', false, 10, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('scholarship_certificate', 'attestation de bourse', 'En cas de bourse : (par ex. du DAAD, d’Erasmus +, d’une université ou d’une fondation), l’attestation de bourse est acceptée comme preuve de financement. La bourse doit couvrir au moins le montant mensuel / annuel susmentionné.', 'financial', false, 11, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('motivation_letter', 'Lettre de motivation', 'Lettre de motivation en allemand ou en français.', 'supporting', true, 12, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('curriculum_vitae', 'Curriculum vitae', 'Curriculum vitae complet avec des informations sur l''école, l''université et la carrière professionnelle ainsi que sur les cours de langue.', 'supporting', true, 13, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('school_leaving_certificate', 'Certificat de fin d''études', 'Preuve de votre certificat de fin d''études (diplôme du Bac).', 'education', true, 14, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('academic_and_employment_records', 'Cursus scolaire/lettres d’emploi', 'Si disponible : preuves des diplômes universitaires / enseignements supérieurs ou des emplois.', 'education', false, 15, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('german_language_certificate', 'Certificat de langue', 'Preuves des connaissances en langue allemande du niveau demandé par l’institution de formation (université ou institut de langue) en Allemagne.', 'language', true, 16, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf'),
  ('health_insurance', 'Assurance maladie', 'Preuve d''une couverture d''assurance maladie légale suffisante en tant qu''étudiant/boursier. Une assurance maladie de voyage n’est pas valable pour faire les études et ne sera pas acceptée.', 'insurance', true, 17, 'https://abidjan.diplo.de/resource/blob/2302994/254c4f2cde58ebca1448f5b0349263a6/merblatt-visa-studenten-fra-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

