  ('passport', 'Passport and 1 copy of the data page', null, 'identity', true, 1, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('residence_permit_country_of_residence', 'valid residence permit for the country of residence', 'If you are a foreigner residing in Kenya, Burundi, Somalia, Eritrea, Sudan or the Seychelles, you have to show a valid residence permit for the country of residence.', 'residence_status', false, 2, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('application_form', '1 completed and duly signed application form', 'A digital application form to be completed online can be found on https://videx-national.diplo.de', 'application', true, 3, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('biometric_photos', '2 current, identical biometric passport photos with a white background', null, 'photo', true, 4, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('admission_direct', 'unconditional letter of admission from a German university', 'Direct admission: The letter of admission must indicate the language in which the studies will be conducted.', 'study_purpose', false, 5, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('admission_study_preparation', 'Conditional notification of admission from a German university AND/OR unconditional notification of admission from a German Studienkolleg AND/OR registration for a study-preparatory language course', 'Study preparation.', 'study_purpose', false, 6, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('application_for_studies_proof', 'Reservation of a place at a university OR confirmation of application (“Bewerberbestätigung”) OR final notification (“endgültige Mitteilung”) from uni-assist OR invitation to take part in the admission test to the preparatory course at the Studienkolleg', 'Application for studies.', 'study_purpose', false, 7, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('proof_of_financing', 'Proof of financing of the stay', 'By one of these options: blocked account for the first year of your stay; OR formal obligation letter (“Verpflichtungserklärung”) by sponsor living in Germany with the creditworthiness (“Bonität”) “proven” (“nachgewiesen”) according to Sections 66 to 68 AufenthG for the entire stay (not older than six months at the time of application); OR scholarship confirmation, stating the duration and the amount of the monthly payment.', 'financial', true, 8, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('tuition_fee_payment', 'proof of payment of tuition fees for the first year of study', 'If the university in Germany charges tuition fees, proof of payment of tuition fees for the first year of study must be provided or the blocked account must be increased by the amount of tuition fees.', 'financial', false, 9, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('educational_documents', 'Bachelor’s or Master’s degree, training or school diplomas, the transcript of records, as well as confirmations from the university, if studies were started but not completed', 'It is not necessary to submit the elementary school diploma. The above documents must be submitted in original.', 'education', true, 10, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('eritrean_university_certificate_confirmation', 'confirmation from the Eritrean “Higher Board of Education” as well as a certification note from the Eritrean Ministry of Foreign Affairs', 'Special case for Eritrean students: your Eritrean university certificate must contain this confirmation and certification note.', 'education', false, 11, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('language_certificate', 'proof of German or English language skills', 'Depending on the language of study, by presenting a recognized language certificate (in Kenya: Goethe-Institut, ÖSD, IELTS or TOEFL) - unless the German university has already tested the language skills during the admission procedure (this must be explicitly stated in the admission letter). If you have already studied in Kenya (in English), then the submission of a language certificate for English at the university and thus also at the Embassy is usually not required (this must also be explicitly stated in the admission letter).', 'language', false, 12, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('curriculum_vitae', 'Curriculum vitae in German or English, gapless', null, 'personal', true, 13, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('motivation_letter', 'A conclusive letter of motivation in German or English, written by yourself', 'Detailing the reason for the chosen studies subject, chosen university and what consequences you envision the studies will have on your future.', 'personal', true, 14, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250'),
  ('health_insurance', 'Proof of incoming health insurance coverage', 'Valid for three months beginning with date of entry to Germany.', 'insurance', true, 15, 'https://nairobi.diplo.de/ke-en/service/visa-entry/2629250-2629250')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

