  values ('gh', 'de', 'study', 'National Visa for Studies', 1, date '2026-09-12', 'German Embassy Accra', 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324', null, null, 7500, 'EUR', false, null, 'pending', null, null, null, '3dff1cd69fef07bd3c0cd402f05307e2c58f3d74554fe001cca050783f6614c8')
