insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'Passport', 'Original passport + copy of data page; valid for at least 6 more months and at least two free pages.', 'identity', true, 1, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('birth_certificate', 'Birth certificate', 'Based on first registration.', 'civil_document', true, 2, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('school_leaving_certificates', 'School leaving certificates', null, 'education', true, 3, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('waec_certificates', 'WAEC-certificates: BECE and WASSCE', null, 'education', true, 4, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('cv', 'Curriculum vitae (CV)', 'Including specification of the certificates, diplomas and qualifications obtained; professional training; work experience.', 'personal_document', true, 5, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('motivation_letter', 'Letter of motivation', 'Signed by the applicant; detailed expectations of planned stay, anticipated career and personal benefits as well as future plans.', 'personal_statement', true, 6, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('admission_letter', 'Admission Letter', 'From a German University, stating the course, the starting date and the language of instruction.', 'education', true, 7, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('language_proof', 'Proof of the language skills in the language of instruction', 'Required if not confirmed by the university in the admittance notification; without a preparatory language course as a rule at least B2 in the language of instruction.', 'language', false, 8, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('proof_of_financial_means', 'Proof of adequate financial means', 'Either a blocked account with a minimum amount of 11,904.00 Euro for the first year (992.00 Euro per month), or a formal obligation ("Verpflichtungserklärung") according to Sec. 66 to 68 of the German Residence Act covering the entire duration of stay, signed by a person living in Germany at the local competent office in Germany. A formal obligation can only be accepted with the remark “nachgewiesen.” and must not be older than 6 months on the intended date of entering Germany.', 'financial', true, 9, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('study_fees_university_letter', 'Letter from the university with the amount of study fees for the first year / payment plan', 'Required in case of study fees.', 'financial', false, 10, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('study_fees_sponsor_letter', 'Letter of your sponsor confirming the sponsorship of your study fees', 'Required if a third party is sponsoring your study fees.', 'financial', false, 11, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('study_fees_sponsor_id', 'ID of your sponsor in copy (ID card or passport)', 'Required if a third party is sponsoring your study fees.', 'identity', false, 12, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('study_fees_sponsor_bank_statements', 'Bank statements of the last 3 months of your sponsor', 'Required if a third party is sponsoring your study fees.', 'financial', false, 13, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('study_fees_own_bank_statements', 'Bank statements of the last three months', 'Required if you have sufficient means to finance all study fees yourself.', 'financial', false, 14, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('study_fees_payment_confirmation', 'Letter of the university confirming your payment', 'Required if you have paid your study fees for the first year (2 semesters) in advance.', 'financial', false, 15, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('health_insurance', 'Health insurance', 'Incoming health insurance from entry to enrollment and proof of national/statutory health insurance starting from enrollment. A travel health insurance is not sufficient.', 'insurance', true, 16, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('residence_permit_ghana', 'Residence permit for Ghana', 'Only for applicants with a nationality other than Ghanaian, Liberian or Sierra Leonean; upload residence permit and additional documents such as rent contract, working contract, electricity bills etc.; if residing in Ghana upload additionally Non-Citizen Ghana Card.', 'residence', false, 17, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('proof_of_previous_or_current_academic_studies', 'Proof of previous or current academic studies', 'If applicable, e.g. Higher National Diploma/University degree with transcripts, professional training.', 'education', false, 18, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('proof_of_work_experience', 'Proof of work experience', 'If applicable: work contract, statement of employer, salary slips.', 'employment', false, 19, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('biometric_photograph', '1 biometric photograph', 'Not older than 6 months; uniform white background; size: 3.5x4,5 cm; not glued or stapled to the application form.', 'photo', true, 20, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324'),
  ('original_documents', 'Original documents', 'Bring original documents to the interview; the information on which documents are needed is provided in the Consular Service Portal.', 'supporting_document', true, 21, 'https://accra.diplo.de/gh-en/service/-visainformation/2615324-2615324')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

