  )
  values ('za', 'de', 'study', 'National Visa for General Studies', 1, date '2026-09-13', 'German Missions in South Africa', 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf', 4, 4, null, null, false, null, 'pending', null, null, null, 'e9049a0fcaf14724d12d4003c70134ae3906fee789feee9e94a495086543cd56')
  on conflict on constraint corridors_corridor_version_key do nothing
  returning id
