insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('application_form', 'One (1) fully completed and signed application including declaration pursuant to Section 54 Residence Act', null, 'application', true, 1, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('passport_photo', 'One (1) recent biometric passport photo', 'see specimen photos', 'photo', true, 2, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('passport', 'Valid passport', 'personally signed and with at least two (2) completely empty pages', 'passport', true, 3, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('passport_data_page_copy', 'One (1) uncertified copy of the data page of your valid passport', null, 'passport', true, 4, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('proof_of_admittance', 'Proof of admittance to the study course/preparatory college', 'original and one (1) copy, including information on the language of instruction', 'education', true, 5, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('other_academic_qualifications', 'Certificates of other academic qualifications', 'Where available: original and one (1) copy', 'education', false, 6, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('curriculum_vitae', 'Curriculum vitae', null, 'personal', true, 7, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('letter_of_motivation', 'Letter of motivation', null, 'personal', true, 8, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('language_skills_proof', 'Proof of the language skills in the language of instruction for the study course or the preparatory course', 'Where not confirmed by the university in the admittance notification: without a preparatory language course as a rule at least B2 in the language of instruction; original and one (1) copy. The certificate must be dated within the last 12 months.', 'language', false, 9, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('proof_of_financial_means', 'Proof of adequate financial means', 'Proof must be submitted with the application of financial means for at least one year, which is at least € 11 904. To stay in Germany the applicant must have at their disposal at least € 992 per month.', 'financial', true, 10, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('blocked_account_confirmation', 'Official confirmation of the opening of the account', 'In the case of financing in the form of a blocked account: Open the blocked account in good time BEFORE you apply for a visa. When applying for a visa, only the official confirmation of the opening of the account including information on the amount paid in and the amount available per month will be accepted. A confirmation which does not include this information is not sufficient.', 'financial', false, 11, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('health_insurance', 'Proof of adequate health insurance cover', 'If as a student you want to take out statutory health insurance, this insurance can only begin when you take up residence in Germany and after enrolment. If you enter Germany beforehand, private health insurance must be taken out for the period prior to enrolment and registering for statutory health insurance. Travel health insurance and incoming travel insurance can contain exclusions if a long-term or permanent stay is planned.', 'insurance', true, 12, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('preparatory_course_or_internship_acceptance', 'Acceptance for preparatory language course or internship', 'In the case of preparatory language course or internship', 'education', false, 13, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('proof_of_habitual_abode_in_south_africa', 'Proof of habitual abode by South Africa', 'Applicant of a nationality other than South African', 'residence', false, 14, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('certified_german_translations', 'Certified German translation', 'Documents not in the English language must be submitted with a certified German translation. A translation of the personal data page of the passport is, however, not required.', 'translation', false, 15, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf'),
  ('original_certificates_diplomas', 'Certificates, diplomas, etc.', 'must be presented in the original. Your original documents will be returned to you once your application has been processed.', 'supporting_document', true, 16, 'https://southafrica.diplo.de/resource/blob/2295120/f54d83ab0f7ab8b0aa39f2b3239c86f2/visad-mb-study-data.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

