  values ('ng', 'de', 'relocation', 'Application for a Visa for the Purpose of Family Reunion child joining foreign / german parent in Germany', 1, date '2026-09-04', 'German Embassy Abuja / Consulate General Lagos', 'https://nigeria.diplo.de/resource/blob/2191572/0b41e7a9ba65f455020154ff65889838/checklist-kindernachzug-data.pdf', 20, null, 7500, 'EUR', true, timestamptz '2026-09-04T11:11:00.334Z', 'approved', null, timestamptz '2026-09-04T11:11:00.334Z', null, '0807a81bdea7a06b50166557dbf0f50a2f388e170f6966eced1fa28450f002b9')
