  ('photograph', 'One recent photograph', 'Less than six months old with good resemblance, passport-size (3.5cm x 4.5cm) in colour.', 'photo', true, 2, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('current_passport', 'Current passport', 'Valid for at least 3 months beyond the intended duration of stay in the Schengen area, and at least 2 blank pages to affix the visa. Copies of passport pages must be in colour.', 'passport', true, 3, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('previous_passports', 'Previous passports (if any)', 'Coloured copies of bio page(s) and of previous Schengen visas and entry/exit stamps.', 'passport', false, 4, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('introduction_letter_applicant', 'Introduction letter from the applicant', 'Introducing himself/herself, explaining the purpose, duration & itinerary of the visit.', 'letter', true, 5, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('social_ties_proof', 'Proof of social ties to home country', 'Marriage certificate, child(ren)’s birth certificate(s), proof of employment, company registration, or similar.', 'supporting_document', true, 6, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('employer_letter', 'Introductory letter from employer', 'If employed: printed on company letter head, including approved period of leave of absence.', 'employment', false, 7, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('student_documents', 'Introductory letter from School, school ID, admission letter and academic transcripts', 'If student: introductory letter from School, printed on school’s letterhead, school ID, admission letter and academic transcripts.', 'education', false, 8, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('cac_registration', 'CAC registration of company', 'If self-employed.', 'business', false, 9, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('travel_medical_insurance', 'Overseas travel medical insurance valid for all Schengen-countries', 'The insurance has to cover the applicant for the entire duration of the stay in the Schengen area for a minimum coverage of 30,000 EUR for all risks, e.g. accident, illness, medical emergency evacuation, etc.', 'insurance', true, 10, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('transport_proof', 'Proof of transport', 'Round trip flight/train reservation, car rental agreement (if applicant is travelling to several Schengen states, proof of transport within Schengen).', 'travel', true, 11, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('accommodation_proof', 'Proof of accommodation', 'Hotel bookings or host guarantee/sponsorship of accommodation covering the whole duration of the intended stay.', 'accommodation', true, 12, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('minor_one_parent_consent', 'Written consent from the other parent or guardian', 'In case of minors (less than 18 years) travelling with one parent only: including contact details, photocopies of passports or other ID with photo and signature, birth certificate of the minor, unless parent has sole custody. Documentation of sole custody or guardianship must be provided.', 'minor', false, 13, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('sole_custody_guardianship_proof', 'Documentation of sole custody or guardianship', 'Must be provided unless parent has sole custody, in case of minors travelling with one parent only.', 'minor', false, 14, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('minor_travelling_alone_consent', 'Written consent from both parents or guardian(s)', 'In case of minors (less than 18 years) travelling alone: including contact details, photocopies of passports or other ID with photo and signature, birth certificate of the minor.', 'minor', false, 15, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('minor_third_person_consent', 'Written consent from both parents or guardian(s)', 'In case of minors (less than 18 years) travelling with 3rd person: including contact details, photocopies of passports or other ID with photo and signature of both parents/guardian(s) and 3rd party, birth certificate of the minor.', 'minor', false, 16, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('salary_bank_statement', 'Original personal bank statement of account to which salary is paid into', 'If applicant is employed: showing movements in the last three months duly stamped and signed by the bank.', 'financial', false, 17, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('pay_slips', 'Pay slips for the last three months', 'If applicant is employed.', 'financial', false, 18, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('company_bank_statement', 'Company bank statement', 'If applicant is business owner: showing movements in the last three months duly stamped and signed by the bank.', 'financial', false, 19, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf'),
  ('proof_of_pocket_money', 'Proof of pocket money in their own name', 'All applicants have to provide proof of pocket money in their own name even if their trip is fully sponsored.', 'financial', true, 20, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/tourist-visa-checklist.pdf')
