  ('home_institution_enrolment', 'Documentation showing that your are enrolled at an educational institution in your home country', 'Required if you are a guest or exchange student.', 'education', false, 3, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education'),
  ('self_support_documentation', 'Documentation showing that you can support yourself during your stay in Denmark', 'Bank statement showing date of the statement (maximum 30 days old at the time of submission of application), your full name, balance and currency; or documentation showing that your financial support is secured via a scholarship or a student loan. If you are to pay a tuition fee and have already paid tuition for the first semester, this is accepted as documentation showing that you have sufficient funds and you do not need to provide additional documentation.', 'financial', true, 4, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education'),
  ('parental_consent_declaration', 'Declaration of consent from your parents', 'Required if you are under 18 years old. The declaration must be signed by both of your parents and allows you to study in Denmark.', 'family', false, 5, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education'),
  ('birth_certificate_and_parents_passport_copies', 'Copy of your birth certificate and a copy of the data page in your parents'' passport', 'Required if you are under 18 years old.', 'family', false, 6, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education'),
  ('school_declaration_proper_residence_study_condit', 'Declaration of proper residence and study conditions', 'If the applicant is under 18, the school must sign and stamp a declaration that it will ensure that the applicant has proper residence and study conditions in Denmark.', 'education', false, 7, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education'),
  ('sworn_declaration', 'Sworn declaration', 'Must be signed and attached if you do not sign the application with MitID.', 'application', false, 8, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education'),
  ('biometrics', 'Biometric features', 'You must have a facial photo taken and your fingerprints recorded. If you have submitted an online application form, you must have your biometric features recorded no later than 14 days after you submitted your application. If you submit your application to a Norwegian diplomatic mission, you must also submit one passport photo.', 'biometric', true, 9, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education'),
  ('passport_photo', 'One passport photo', 'Required if you submit your application to a Norwegian diplomatic mission.', 'photo', false, 10, 'https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher%20education')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

