insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('applyvisa_cover_letter', 'The cover letter from the online application website “Applyvisa”', 'Original cover letter with signature required.', 'application_form', true, 1, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('passport_photo', 'One passport-size photograph', 'Less than six months old in color with good resemblance (3.5cm / 4.5cm).', 'photo', true, 2, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('current_passport', 'Current passport', 'Should be valid for at least three months beyond the intended duration of stay in the Schengen area and must have at least two blank pages to affix the visa.', 'passport', true, 3, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('former_travel_documentation', 'Documentation on former travels abroad', 'If relevant an old passport should be attached to the application.', 'travel_history', false, 4, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('company_cover_letter', 'Cover letter from your organization or company', 'Containing name and designation of the applicant signed by an authorized person in the company; should outline the applicant’s purpose of visit, names and address of the company he/she intends to visit and period/place of intended stay. Any planned future visits to the Schengen area should be included.', 'employment', true, 5, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('owner_business_documents', 'Copies of business documents', 'If applicant is owner of the company, such as registration papers (registration certificates, tax clearance certificates, bills of lading, etc.).', 'business', false, 6, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('invitation_letter', 'Signed invitation letter from the host/host company', 'Containing name of the invited person, purpose of visit, dates of the intended stay, and which costs are covered by host (boarding & lodging). Electronic invitation (VU1) is recommended.', 'invitation', true, 7, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('travel_medical_insurance', 'Overseas travel medical insurance', 'Valid for all Schengen countries. The insurance has to cover the applicant for the entire duration of the stay in the Schengen area at a minimum coverage of 30,000 EUR for all risks, e.g. accident, illness, medical emergency evacuation, etc.', 'insurance', true, 8, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('round_trip_flight_reservation', 'Round trip flight reservation', 'If applicant is travelling to several Schengen states, proof of intra-Schengen flight reservation, train itinerary or car rental.', 'travel', true, 9, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('accommodation_proof', 'Proof of accommodation', 'Hotel bookings or host guarantee/sponsorship of accommodation covering the whole duration of the intended stay.', 'accommodation', true, 10, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('financial_support_employed', 'Evidence of source of financial support/means of subsistence', 'If applicant is employed: pay slips for the last three months, employment contract, bank statement for account through which salary is paid.', 'financial', false, 11, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('financial_support_business_owner', 'Evidence of source of financial support/means of subsistence', 'In case applicant is the owner of the company: copies of company registration documents, company’s bank statement, tax clearance receipt, etc. are required.', 'financial', false, 12, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf'),
  ('personal_bank_statement', 'Original personal bank statement', 'Showing movements in the last three months and duly stamped and signed by the bank. All applicants have to provide proof of pocket money in their own name even if their trip is fully sponsored.', 'financial', true, 13, 'https://visa.vfsglobal.com/one-pager/denmark/Nigeria/english/pdf/business_new.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

