select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('passport', 'a current passport or other valid travel documentation', null, 'identity', true, 1, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('cas', 'a Confirmation of Acceptance for Studies (CAS) from your course provider', null, 'study', true, 2, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('funds_proof', 'proof you have enough money to support yourself and pay for your course', 'This will vary depending on your circumstances.', 'financial', false, 3, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('atas_certificate', 'a valid ATAS certificate', 'Required if your course and nationality require it.', 'study', false, 4, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('parental_consent', 'proof of parental or other legal guardian consent', 'If you’re under 18.', 'consent', false, 5, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('relationship_to_parent_guardian', 'proof of your relationship to your parent or guardian', 'If you’re under 18.', 'family', false, 6, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('tuberculosis_test_results', 'your tuberculosis test results', null, 'health', true, 7, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('financial_sponsor_consent', 'written consent for your application from your financial sponsor', 'If you’ve received sponsorship for your course fees and living costs in the last 12 months.', 'consent', false, 8, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('written_parental_consent', 'written consent from both parents or legal guardians (or one parent if they have sole responsibility)', 'If you’re under 18. This must include their consent for your visa application, your living and care arrangements in the UK, and your travel to the UK.', 'consent', false, 9, 'https://www.gov.uk/student-visa/documents-you-must-provide'),
  ('birth_certificate', 'a copy of your birth certificate (or another government issued document)', 'If you’re under 18. It must show the names of your parents.', 'family', false, 10, 'https://www.gov.uk/student-visa/documents-you-must-provide')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

