select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('application_form', 'Application Form – signed and dated', null, 'application', true, 1, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('passport_and_copies', 'Passport + previous passports + 2 Photographs + COPIES of all passport pages (including blanks)', null, 'identity', true, 2, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('visa_fee_payment', 'Visa Fee Payment', 'Proof of visa fee payment is to be submitted with the application.', 'fee', true, 3, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('residency_card', 'Residency Card + COPY of the residency card', null, 'residence', true, 4, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('application_letter', 'Application letter - signed and dated', 'Explaining why you want to come to Ireland. It must include your full name, postal address, contact details and the commitment from you that you will obey the conditions of your visa in full, not rely on public services (e.g. public hospitals) or become a burden on the State, and leave Ireland before your immigration permission expires.', 'application', true, 5, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('accommodation', 'Accommodation in Ireland (e.g. hotel, etc.)', null, 'travel', true, 6, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('employer_letter_and_payslips', 'Letter from the employer (NOT EMPLOYMENT CONTRACT) including the following information', 'Type of employment (temporary, indefinite, etc.), how long you have been employed there; the dates you will be absent from your employment and the date you will be returning to work in that employment; 3 most recent payslips.', 'employment', false, 7, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('self_employment_evidence', 'If you are self-employed you must provide documentary evidence of your business/company', 'Official document from the company registrar; latest income tax return; up to date bank statements (from the past six months) from your business bank account.', 'employment', false, 8, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('study_letter', 'Study- Letter from your college including the following information', 'The course you are studying, how many years you have been a student there; how many years or terms you have left at that college and that you will be returning there following your visit to Ireland.', 'education', false, 9, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('property_evidence', 'Property - Evidence of any property you own or rent , Lease agreement or Title deed', null, 'financial', true, 10, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('personal_bank_statement', 'Finances', 'If you are paying for your own visit include an up-to-date 6 months DETAILED bank statement. It must be original and on headed bank paper, must include your name and address; show money paid in and out of the account over the last 6 months; and include a written explanation of any large movements of money in or out of your account, if appropriate.', 'financial', false, 11, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('sponsor_letter_and_finances', 'If you are supported by a spouse, partner or member of your family, they should provide', 'An original, signed and dated letter stating that they are financing your trip; bank statement to the same criteria as described above; evidence of their relationship to you e.g. marriage certificate.', 'financial', false, 12, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf'),
  ('previous_visa_refusal_details', 'Previous visa refusal details', null, 'history', true, 13, 'https://assets.ireland.ie/documents/2025_07_08_VISIT_TOURIST_CHECKLISST.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

