insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('avats_application_form', 'AVATS application form', 'The online completed form must be printed, signed and dated by the applicant.', 'application', true, 1, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('vfs_payment_receipt_and_completed_checklist', 'Payment receipt and checklist', 'If applying through VFS you must provide a printed copy of your VFS payment receipt, showing the same visa application number (IRLXXXXXXXX) as per 1.1. You must also supply this completed checklist.', 'application', false, 2, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('passport_photos', 'Passport photos', 'Two photos meeting the requirements at https://www.irishimmigration.ie/photograph-rules-for-visa-applications/.', 'identity', true, 3, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('current_passport', 'Current passport', 'Must be valid for at least 12 months after the date of arrival in Ireland.', 'identity', true, 4, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('copies_of_previous_passports', 'Copies of previous passport(s)', 'Photocopies only of the biographic pages and all stamps/visas from any previous passports. Blank pages do not need to be copied. Details of any lost or missing passports should be mentioned in 3.1.', 'identity', true, 5, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('application_letter', 'Application letter', 'Outline the reasons for travelling to Ireland. State whether you have any family members of friends in Ireland or the United Kingdom, and if so list their details.', 'purpose_of_travel', true, 6, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('employment_permit_and_supporting_employer_docume', 'Employment permit holders', 'Provide the employment permit and your employment permit application form. You must also provide a letter from the Irish employer confirming your hiring, and a copy of your contract showing your roles, responsibilities and remuneration.', 'work_permission', false, 7, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('atypical_working_scheme_approval_and_supporting_', 'Atypical permission holders', 'Provide the atypical working scheme letter of approval, issued by the Department of Justice. You must also provide a letter from the Irish employer confirming your hiring, the nature of your employment and a copy of your contract. Additional requirements may apply depending on what activities you will be undertaking in Ireland.', 'work_permission', false, 8, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('hosting_agreement_and_supporting_employer_docume', 'Scientific researchers', 'Provide the hosting agreement, obtained through your research organisation in Ireland. You must also provide a letter from the Irish employer confirming your hiring, and a copy of your contract.', 'work_permission', false, 9, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('qualifications_or_work_experience_evidence', 'Evidence of your qualification or work experience', 'Provide evidence of your qualifications and previous work experience in the appropriate field. Such evidence could include letters from current and previous employers, recent payslips, professional certificates or qualifications.', 'employment', true, 10, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('bank_statement', 'Bank statement', 'You must provide an up-to-date bank statement, showing what money has been paid into and out of the account over the last six months, and showing sufficient funds to cover your costs.', 'financial', true, 11, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('police_clearance_certificates', 'Police clearance certificates', 'You must provide a police clearance certificate (PCC) for any country where you held residence permission (including Ireland or the United Kingdom) in the five years prior to your application. For country of current residence PCCs should be dated within six months of application. For countries of previous residence, within six month of departure.', 'character', true, 12, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('visa_refusal_letter_and_refusal_notice', 'If you have previous visa refusals for any country', 'Provide a letter detailing the refusals (country, reason for travel, dates, reasons for refusal etc.). You must also provide the refusal letter from the issuing country. If unavailable, explain why.', 'history', false, 13, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf'),
  ('medical_or_travel_insurance', 'Medical insurance', 'Evidence of medical or travel insurance does not need to be provided with your application; however, if a visa issues, it must be produced on arrival in Ireland.', 'insurance', false, 14, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Employment.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

