  values ('km', 'ie', 'study', 'Study Visa (Long Stay D)', 1, date '2026-09-14', 'Irish Naturalisation and Immigration Service', 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf', null, null, null, null, false, null, 'pending', null, null, null, '6a3b53fff5fe087ad10d149e44ef0d5d9e173e68cd2a8066336dbfdef459bb2d')
