insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('avats_application_form', 'AVATS application form', 'The online completed form must be printed, signed and dated by the applicant.', 'application', true, 1, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('vfs_payment_receipt_and_completed_checklist', 'Payment receipt and checklist', 'If applying through VFS you must provide a printed copy of your VFS payment receipt, showing the same visa application number (IRLXXXXXXXX) as per 1.1. You must also supply this completed checklist.', 'application', false, 2, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('passport_photos', 'Passport photos', 'Two photos meeting the following requirements: https://www.irishimmigration.ie/photograph-rules-for-visa-applications/', 'identity', true, 3, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('current_passport', 'Current passport', 'Must be valid for at least 12 months after the date of arrival in Ireland.', 'identity', true, 4, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('copies_of_previous_passports', 'Copies of previous passport(s)', 'Photocopies only of the biographic pages and all stamps/visas from any previous passports. Blank pages do not need to be copied. Details of any lost or missing passports should be mentioned in 3.1.', 'identity', true, 5, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('application_letter', 'Application letter', 'Outline the reasons for travelling. State whether you have any family members of friends in Ireland or the United Kingdom, and if so list their details.', 'purpose_of_travel', true, 6, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('letter_of_acceptance', 'A valid offer to study a course listed on the ILEP', 'Provide a letter from the HEI confirming your unconditional placement on an eligible course of study in Ireland. The letter should confirm that you have been accepted and enrolled on a course of full-time education, involving a minimum of 15 hours organised daytime tuition each week, give details of the course that you will be studying, the fees payable, the amount of fees that you have paid and whether your provider has taken out medical insurance on your behalf, if applicable.', 'study', true, 7, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('confirmation_fees_paid', 'Confirmation from HEI that requisite fees have been paid', 'Provide evidence that you have paid the requisite fees at time of visa application. Where the course fees are less than €6,000, you must pay fees in full to the college before to applying for your visa. Where the course fees are more than €6,000, you must pay at least this amount before applying for your visa. Evidence of this should be visible in your letter of acceptance. This minimum amount is an Immigration requirement. However, your course provider may ask for full payment of fees.', 'financial', true, 8, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('eft_copies_or_valid_receipt', 'Electronic transfer of funds (EFTs)', 'You must provide copies of ETFs to the Irish Bank of the HEI, showing the beneficiary’s name, address, bank details and the same details for sender or a valid receipt showing that the course fees have been lodged to an approved student fees payment service. For example, the electronic fee payment service offered by Pay to Study, formerly known as International Student Payments Service (ISPS).', 'financial', true, 9, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('previous_educational_qualifications', 'Previous educational qualifications (inc. DigiLocker)', 'You must provide evidence that you have the ability to all follow your chosen course. This must include all qualification awards and individual semester mark sheets. Where possible, applicants from India should also submit DigiLocker versions of their qualifications alongside originals. Secondary level qualifications are only required when you are applying for a level 7 or 8 bachelor degree in Ireland.', 'education', true, 10, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('english_language_certification', 'English language certification', 'Provide a certificate from an accepted test provider to show you have the required English language ability: https://www.irishimmigration.ie/coming-to-study-in-ireland/english-language-requirements-for-study-visas/.', 'education', true, 11, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('employment_history', 'Employment history', 'If applicable, provide evidence of your employment history since leaving fulltime education. Evidence should include up-to-date letters from your current employer, recent payslips, letters of resignation from previous employers etc.', 'employment', false, 12, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('personal_bank_statements', 'Personal finances', 'An overview of the finances you must show is available online: https://www.irishimmigration.ie/coming-to-study-in-ireland/what-are-my-study-options/a-fee-paying-private-primary-or-secondary-school/information-on-student-finances/. You must provide personal bank statements.', 'financial', true, 13, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('sponsor_letters_and_identity_documents', 'Sponsored finances', 'For any sponsors, you must provide signed letters of sponsorship and copies of their national identity documents. Gold valuations, chit funds and volatile funds (crypto or market-linked funds) are not accepted. Funds should be liquid and in verifiable bank accounts.', 'financial', false, 14, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('financial_summary_form', 'Financial summary form (FSF)', 'The FSF attempts to help you understand and summarise your financial requirements: https://www.irishimmigration.ie/coming-to-study-in-ireland/what-are-my-study-visa-options/how-to-apply-for-long-term-study-visa/#guide.', 'financial', true, 15, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('private_medical_insurance', 'Private medical insurance', 'Private Medical Insurance cover is required.', 'insurance', true, 16, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('police_clearance_certificates', 'Police clearance certificates', 'You must provide a police clearance certificate (PCC) for any country where you held residence permission (including Ireland or the United Kingdom) in the five years prior to your application. For country of current residence PCCs should be dated within six months of application. For countries of previous residence, within six month of departure.', 'character', true, 17, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('previous_visa_refusals', 'Previous visa refusals', 'Provide a letter detailing any refusals (country, reason for travel, dates, reasons for refusal etc.) and the refusal letters from the issuing country. If unavailable, explain why.', 'history', true, 18, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

