  ('financial_summary_form', 'Financial summary form (FSF)', 'The FSF attempts to help you understand and summarise your financial requirements: https://www.irishimmigration.ie/coming-to-study-in-ireland/what-are-my-study-visa-options/how-to-apply-for-long-term-study-visa/#guide.', 'finances', true, 15, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('private_medical_insurance', 'Private medical insurance', 'Private Medical Insurance cover is required.', 'medical', true, 16, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('police_clearance_certificates', 'Police clearance certificates', 'You must provide a police clearance certificate (PCC) for any country where you held residence permission (including Ireland or the United Kingdom) in the five years prior to your application. For country of current residence PCCs should be dated within six months of application. For countries of previous residence, within six month of departure.', 'criminal_record', true, 17, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf'),
  ('previous_visa_refusals', 'Previous visa refusals', 'Provide a letter detailing any refusals (country, reason for travel, dates, reasons for refusal etc.) and the refusal letters from the issuing country. If unavailable, explain why.', 'travel_history', true, 18, 'https://assets.ireland.ie/documents/NDVO_20250708_IRL_Visa_checklist_Study.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

