  ('passport', 'Passport', 'Must have a minimum validity of 8 months.', 'passport', true, 2, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('passport_photo', '1 passport photo according to ICAO Standards Pg14 (3.9.1.5)', null, 'photo', true, 3, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('cover_letter', 'Cover letter with sufficient reason for a long-term visit', null, 'supporting_letter', true, 4, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('medical_travel_insurance', 'Medical and travel insurance', 'Must be valid for the Schengen area; must have a minimum medical coverage of €30,000; must include name, surname, and passport number; assurance that the coverage will be valid for non-applicable residents.', 'insurance', true, 5, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('proof_of_accommodation', 'Proof of accommodation', 'Declaration of proof: provided where the host will be providing the applicant with free accommodation; declaration of proof must be signed and stamped by a local lawyer or notary; together with this, a copy of the host’s ID Card, and proof of residence, such as a utility bill, must be provided; if the applicant will be accommodated at a secondary address this must be stated. Lease Agreement: must be signed by both parties and stipulate the duration, home address, and name of applicant, and amount of rent. Hotel Booking: minimum of 14 consecutive nights from date of arrival in Malta.', 'accommodation', true, 6, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('declaration_of_proof', 'Declaration of proof', 'This is to be provided in those cases where the host will be providing the applicant with free accommodation. Declaration of proof must be signed and stamped by a local lawyer or notary. Together with this, a copy of the host’s ID Card, and proof of residence, such as a utility bill, must be provided. If the applicant will be accommodated at a secondary address this must be stated.', 'accommodation', false, 7, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('lease_agreement', 'Lease Agreement', 'Must be signed by both parties and stipulate the duration, home address, and name of applicant, and amount of rent.', 'accommodation', false, 8, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('hotel_booking', 'Hotel Booking', 'Minimum of 14 consecutive nights from date of arrival in Malta.', 'accommodation', false, 9, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('bank_statement', 'Bank Statement of the past three months', 'Must have sufficient means for the duration of stay.', 'financial', true, 10, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('flight_itinerary', 'Flight ticket details', 'Full flight itinerary must be provided, indicating applicant’s name, date of flight, and all stops - preferably transiting outside the Schengen area.', 'travel', true, 11, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('full_passport_copy', 'Full passport copy', null, 'passport', true, 12, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf'),
  ('letter_of_acceptance', 'Original Letter of Acceptance by the Maltese Education Institution', 'Including details of the course, duration and fees with proof of payment.', 'study', true, 13, 'https://identita.gov.mt/central-visa-unit-national-visa-long-stay-visa/'),
  ('education_establishment_letter', 'Letter from their education establishment', 'Those in full-time education should submit a letter from their education establishment clearly indicating the course of studies being followed.', 'study', false, 14, 'https://identita.gov.mt/central-visa-unit-national-visa-long-stay-visa/'),
  ('documents_in_english', 'All documents should be submitted in English', null, 'format', true, 15, 'https://identita.gov.mt/wp-content/uploads/2024/12/Documentation-required-for-long-term_non-tourism.pdf')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

