  ('visa_application_form', 'A visa application form', 'Filled via the e-konsulat system, printed and signed.', 'application', true, 1, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('photo', 'A 3.5 x 4.5 cm colour photo', 'The photo must be sharp, taken against white background and printed on a quality paper; newer than 6 months; taken en face, clearly showing the eyes and face on both sides from the top of the head to the top of the shoulders with the face covering 70-80% of the photo; taken without any headwear.', 'photo', true, 2, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('passport', 'Passport', 'Issued within last ten years, valid for at least three months from the expected return date, with at least two blank pages for visas.', 'travel_document', true, 3, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('passport_copy', 'A copy of the passport page with personal data and the photo', null, 'travel_document', true, 4, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('medical_insurance', 'Documentation confirming the possession of medical travel insurance or documentation confirming the possession of health insurance', 'Medical travel insurance with an insured amount of no less than EUR 30,000 must be valid for the period of the foreigner’s intended stay within the Republic of Poland and must cover all expenses that may be incurred during the stay, including: the need for return travel for medical reasons, the need for urgent medical assistance, emergency hospital treatment, or death.', 'insurance', true, 5, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('legal_residence_id_copy', 'A copy of an ID document to confirm legal residence within the consular district of your application', null, 'residence', true, 6, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('proof_of_means_work', 'The employment contract', 'Listed under proof that you have enough means of subsistence for work visas.', 'financial', true, 7, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('accommodation_proof', 'A proof of accommodation', 'For example, an official invitation or a hotel booking or reservation.', 'accommodation', true, 8, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('purpose_of_stay_documents', 'Documents confirming the purpose of your stay Poland', null, 'purpose', true, 9, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('flight_reservation_copy', 'A copy of the flight ticket reservation', 'Containing the flight details and booking number.', 'travel_itinerary', true, 10, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('minor_parental_consent', 'Written consent of the child’s/minor’s parent(s) to apply for a visa, confirmed by a notary', 'Required when applying for a visa for a minor.', 'minor_documents', false, 11, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('minor_single_guardian_proof', 'Proof that there is only one guardian', 'If there is only one guardian, it should be proved by a birth certificate, a court decision on exclusive parental custody or a death certificate of the other parent.', 'minor_documents', false, 12, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('parents_passport_copies', 'Originals and copies of parents'' passports', 'Required when applying for a visa for a minor.', 'minor_documents', false, 13, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa'),
  ('minor_birth_certificate', 'An original and a copy of a birth certificate', 'Required when applying for a visa for a minor.', 'minor_documents', false, 14, 'https://www.gov.pl/web/tanzania-en/d-type-national-visa')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

