insert into corridor_requirements
  (corridor_id, doc_key, name, description, category, is_required, sort_order, source_url)
select c.id, v.doc_key, v.name, v.description, v.category, v.is_required, v.sort_order, v.source_url
from c, (values
  ('visa_application_form', 'A visa application form', 'Filled via the e-konsulat system, printed and signed.', 'application', true, 1, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('photo', 'A 3.5 x 4.5 cm colour photo', 'Must be sharp, against white background, printed on quality paper, newer than 6 months, taken en face, clearly showing the eyes and face on both sides from the top of the head to the top of the shoulders with the face covering 70-80% of the photo, and taken without headwear.', 'photo', true, 2, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('passport', 'Passport', 'Issued within last ten years, valid for at least three months from the expected return date, with at least two blank pages for visas.', 'travel_document', true, 3, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('passport_copy', 'A copy of the passport page with personal data and the photo', null, 'travel_document', true, 4, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('health_insurance', 'Document confirming health insurance or travel medical insurance', 'Document confirming coverage by health insurance within the meaning of the Act of 27 August 2004 on health-care benefits financed from public funds, or travel medical insurance with a minimum insurance amount of EUR 30,000, valid throughout the planned stay in Poland, covering expenses connected with return travel for medical reasons, urgent medical aid, emergency hospital treatment or death, with the insurer agreeing to cover costs of health-care benefits directly to the provider on the basis of a bill issued by that provider.', 'insurance', true, 5, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('legal_residence_id_copy', 'A copy of an ID document to confirm legal residence within the consular district of your application', null, 'residence', true, 6, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('proof_of_funds', 'Proof that you have enough means of subsistence', 'In the form decided by the mission.', 'financial', true, 7, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('accommodation_proof', 'A proof of accommodation', 'For example, an official invitation or a hotel booking or reservation.', 'accommodation', true, 8, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('purpose_of_stay_documents', 'Documents confirming the purpose of your stay Poland', null, 'purpose', true, 9, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('flight_reservation_copy', 'A copy of the flight ticket reservation for the planned journey to the Schengen area and return to the place of departure', null, 'travel_itinerary', true, 10, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('acceptance_letter', 'Letter of acceptance from educational institution in Poland', 'The letter must contain your personal data, what course you have been admitted to or what research work is to be done, course or research duration, date and contact details.', 'study', true, 11, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('study_financial_support', 'Proof of financial support', 'Proof of the scholarship you have been or will be granted, or proof of your personal ability to finance your studies, or proof that a guarantor supports you: a letter from your guarantor confirming sponsorship, proof of solvency of the guarantor (bank account statement for the last 3 months / salary sheet / tax paper) and a photocopy of the guarantor’s identity card.', 'financial', true, 12, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('highest_education_diploma', 'Diploma of your highest education level legalized by the Foreign Ministry', null, 'education', true, 13, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('next_level_education_letter', 'Letter stating that the applicant’s diploma entitles him/her to continue education at the next level', 'Required if the diploma does not contain information concerning the right to continue education at the next level in the country in which educational system the school operates. The letter should be issued by the school or the country’s educational authorities, e.g. Ministry of Education, and should state that the diploma entitles the applicant to continue education at the next level, including the right to apply to a higher education institution.', 'education', false, 14, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('programme_fee_receipt', 'Receipt confirming that the fee for the whole programme was paid', 'Required if the applicant is paying for study, training or research programme; in case of studies longer than 1 year the payment has to cover the first semester of studies.', 'financial', false, 15, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('recognition_information', 'Information about the recognition of their foreign diploma in Poland', 'From July 1, 2025, applicants should submit information about the recognition of their foreign diploma in Poland.', 'education', true, 16, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('secondary_school_leaving_certificate', 'A secondary school leaving certificate or another document issued abroad confirming the right to apply for admission to higher education in Poland', 'Any one of the listed documents: a secondary school leaving certificate issued by a recognized school or educational institution together with legalization of the competent authority; certificates and other documents issued by a school operating in the education system of an EU, OECD, EFTA member state; IB diploma; EB diploma; or certificates and other documents issued abroad and recognized by Kenya, Uganda, etc., under an international agreement, which may be recognized by administrative decision as a document confirming the right to apply for admission to studies in Poland.', 'education', true, 17, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('education_office_decision', 'An administrative decision of Education Office (Kuratorium Oświaty)', 'Recognizing the certificate as a document confirming secondary education in Poland or the right to continue education, including the right to apply for admission to higher education. The decision should be obtained before submitting the visa application.', 'education', true, 18, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('language_proficiency_certificate', 'Certificate of proficiency in the language of instruction', 'Issued at the level required by the Polish University.', 'education', true, 19, 'https://www.gov.pl/web/kenya/d-type-national-visa'),
  ('tuition_fee_payment_proof', 'Proof of payment of the tuition fee', 'In the case of higher education on a fee-based basis, proof of payment of the tuition fee in accordance with the requirements of the Polish University must be submitted.', 'financial', false, 20, 'https://www.gov.pl/web/kenya/d-type-national-visa')
) as v(doc_key, name, description, category, is_required, sort_order, source_url);

